/**
 * Settings → Plugins card for the `dsh-dgx-audio` namespace: first-run server setup and a truthful view of what
 * each configured model has actually been verified to do on this computer. Nothing is contacted automatically;
 * "Test connection" is an explicit user action that asks the host for a reachability probe (no inference).
 */

import { useEffect, useState, useSyncExternalStore } from 'react'
import { probeReachability, type AudioModelView, type AudioRouteView, type AudioRoutesStore, type CapabilityView, type ProbeResult } from './audio-routes.ts'
import { format, type AudioKitKey } from './locale.ts'
import css from './kit.module.css'

interface RouteSetting {
  provider: string
  displayName?: string
  baseURL: string
  apiKeyEnv?: string
  models: Array<Record<string, unknown>>
}

interface AudioSettings { routes?: RouteSetting[] }

export interface AudioServersFace {
  scope: {
    getSnapshot(): { status: 'loading' | 'ready' | 'unavailable', value: AudioSettings | undefined, writable: boolean }
    subscribe(listener: () => void): () => void
    mutate(ops: ReadonlyArray<{ op: 'set', path: readonly string[], value: unknown }>): Promise<void>
  }
  routes: AudioRoutesStore
}

function slug(text: string): string {
  const base = text.normalize('NFKD').toLowerCase().replaceAll(/[^a-z0-9]+/gu, '-').replaceAll(/^-+|-+$/gu, '').slice(0, 32)
  return base === '' ? 'audio-server' : base
}

function capLabel(t: (key: AudioKitKey) => string, cap: CapabilityView | undefined): string {
  switch (cap?.state) {
    case 'verified': return t('capVerified')
    case 'advertised': return t('capAdvertised')
    case 'declared': return t('capDeclared')
    case 'unsupported': return t('capUnsupported')
    default: return t('capUntested')
  }
}

const CAP_LABEL = {
  textStreaming: 'capTextStreaming',
  audioOutput: 'capAudioOutput',
  audioOutputStreaming: 'capAudioOutputStreaming',
  liveInput: 'capLiveInput',
  fullDuplex: 'capFullDuplex',
  bargeIn: 'capBargeIn',
} as const satisfies Record<string, AudioKitKey>

/** Only the capabilities that mean something for this model's mode. */
function capabilityKeys(model: AudioModelView): ReadonlyArray<keyof typeof CAP_LABEL> {
  if (model.mode === 'realtime') return ['liveInput', 'fullDuplex', 'bargeIn']
  if (model.mode === 'transcribe') return []
  return model.output?.audio === true ? ['textStreaming', 'audioOutput', 'audioOutputStreaming'] : ['textStreaming']
}

function modeLabel(t: (key: AudioKitKey) => string, model: AudioModelView): string {
  if (model.mode === 'transcribe') return t('modeTranscribe')
  if (model.mode === 'realtime') return t('modeRealtime')
  return model.output?.audio === true ? t('modeChatSpeech') : t('modeChat')
}

export function AudioServersCard(props: any) {
  const t = (key: AudioKitKey, values?: Record<string, string>) => format(props.t(key), values)
  const face: AudioServersFace = props.audioServers
  const settings = useSyncExternalStore(face.scope.subscribe, face.scope.getSnapshot)
  const live = useSyncExternalStore(face.routes.subscribe, face.routes.getSnapshot)
  const [open, setOpen] = useState(false)
  const [probe, setProbe] = useState<Record<string, ProbeResult | 'running'>>({})
  const [form, setForm] = useState({ name: '', url: '', model: '', mode: 'chat', speech: true, keyEnv: '' })
  const [status, setStatus] = useState<string>('')
  const [saving, setSaving] = useState(false)

  useEffect(() => { void face.routes.refresh() }, [settings])

  if (settings.status === 'unavailable') return null
  const configured: RouteSetting[] = Array.isArray(settings.value?.routes) ? settings.value!.routes! : []
  const liveByProvider = new Map<string, AudioRouteView>(live.routes.map(route => [route.provider, route]))
  const writable = settings.writable

  const write = async (routes: RouteSetting[], done: string) => {
    setSaving(true)
    setStatus(t('saving'))
    try {
      await face.scope.mutate([{ op: 'set', path: ['routes'], value: routes }])
      await face.routes.refresh()
      setStatus(done)
      return true
    } catch (error) {
      setStatus(t('saveFailed', { message: error instanceof Error ? error.message : String(error) }))
      return false
    } finally {
      setSaving(false)
    }
  }

  const add = async () => {
    const name = form.name.trim()
    const url = form.url.trim().replace(/\/+$/u, '')
    const model = form.model.trim()
    if (name === '') { setStatus(t('invalidName')); return }
    if (!/^https?:\/\/[^\s/]+/u.test(url)) { setStatus(t('invalidUrl')); return }
    if (model === '') { setStatus(t('invalidModel')); return }
    const taken = new Set(configured.map(route => route.provider))
    let provider = slug(name)
    for (let n = 2; taken.has(provider); n++) provider = `${slug(name)}-${n}`
    const modelId = `${slug(model.split('/').at(-1) ?? model)}${form.mode === 'transcribe' ? '-transcribe' : ''}`
    const route: RouteSetting = {
      provider,
      displayName: name,
      baseURL: url,
      ...(form.keyEnv.trim() === '' ? {} : { apiKeyEnv: form.keyEnv.trim() }),
      models: [{
        id: modelId,
        name: model,
        upstreamModel: model,
        mode: form.mode,
        ...(form.mode === 'chat' ? { sendModalities: true, outputAudio: form.speech } : {}),
      }],
    }
    if (await write([...configured, route], t('saved'))) setForm({ name: '', url: '', model: '', mode: 'chat', speech: true, keyEnv: '' })
  }

  const remove = async (provider: string, name: string) => {
    if (!window.confirm(t('removeConfirm', { name }))) return
    await write(configured.filter(route => route.provider !== provider), '')
  }

  const test = async (provider: string, model: string) => {
    setProbe(current => ({ ...current, [provider]: 'running' }))
    const result = await probeReachability(provider, model)
    setProbe(current => ({ ...current, [provider]: result }))
    void face.routes.refresh()
  }

  const title = t('cardTitle')
  return (
    <li className={`${css.card} ${open ? css.cardOpen : ''}`} data-testid="dsh-audio-servers-card">
      <button type="button" className={css.header} aria-expanded={open} aria-label={`${t(open ? 'collapse' : 'expand')}: ${title}`} onClick={() => { setOpen(!open) }}>
        <span className={css.headText}>
          <span className={css.name}>{title}</span>
          <span className={css.description}>{t('cardDescription')}</span>
        </span>
        <span className={css.count}>{configured.length}</span>
        <span className={`${css.chevron} ${open ? css.chevronOpen : ''}`} aria-hidden="true">⌄</span>
      </button>
      {open
        ? (
          <div className={css.body}>
            {settings.status === 'loading' ? <p className={css.muted}>{t('loading')}</p> : null}
            {!writable && settings.status === 'ready' ? <p className={css.muted} role="status">{t('readOnly')}</p> : null}
            {configured.length === 0 && settings.status === 'ready'
              ? (
                <div className={css.empty} data-testid="dsh-audio-servers-empty">
                  <p className={css.emptyTitle}>{t('emptyTitle')}</p>
                  <p className={css.muted}>{t('emptyBody')}</p>
                </div>
              )
              : null}
            <ul className={css.routes}>
              {configured.map((route) => {
                const view = liveByProvider.get(route.provider)
                const firstModel = String(route.models?.[0]?.id ?? '')
                const result = probe[route.provider]
                return (
                  <li key={route.provider} className={css.route} data-testid="dsh-audio-server-row">
                    <div className={css.routeHead}>
                      <span className={css.routeName}>{route.displayName ?? route.provider}</span>
                      <code className={css.routeUrl}>{route.baseURL}</code>
                    </div>
                    <div className={css.routeMeta}>
                      {view?.authentication === 'none' || route.apiKeyEnv === undefined
                        ? t('keyless')
                        : view?.credentialPresent === false ? t('keyMissing', { name: route.apiKeyEnv }) : t('keyFrom', { name: route.apiKeyEnv })}
                    </div>
                    <ul className={css.modelList} aria-label={t('models')}>
                      {(view?.models ?? []).map(model => (
                        <li key={model.id} className={css.modelRow}>
                          <span className={css.modelName}>{model.name ?? model.id}</span>
                          <span className={css.pill}>{modeLabel(t, model)}</span>
                          <span className={css.caps}>
                            {capabilityKeys(model)
                              .filter(key => model.capabilities?.[key]?.state !== 'unsupported')
                              .map(key => (
                                <span key={key} className={`${css.cap} ${model.capabilities?.[key]?.state === 'verified' ? css.capVerified : ''}`}>
                                  {t(CAP_LABEL[key])}
                                  {': '}
                                  {capLabel(t, model.capabilities?.[key])}
                                </span>
                              ))}
                          </span>
                        </li>
                      ))}
                    </ul>
                    <div className={css.routeActions}>
                      <button type="button" className={css.secondary} disabled={result === 'running' || firstModel === ''} onClick={() => { void test(route.provider, firstModel) }} data-testid="dsh-audio-server-test">
                        {result === 'running' ? t('testing') : t('test')}
                      </button>
                      <button type="button" className={css.ghost} disabled={!writable || saving} onClick={() => { void remove(route.provider, route.displayName ?? route.provider) }}>
                        {t('remove')}
                      </button>
                      {result !== undefined && result !== 'running'
                        ? <span role="status" className={result.ok ? css.ok : css.bad}>{result.ok ? t('testOk', { detail: result.message }) : t('testFailed', { message: result.message })}</span>
                        : null}
                    </div>
                  </li>
                )
              })}
            </ul>
            <form className={css.form} onSubmit={(event) => { event.preventDefault(); void add() }} data-testid="dsh-audio-server-form">
              <p className={css.formTitle}>{t('addTitle')}</p>
              <label className={css.field}>
                <span className={css.label}>{t('fieldName')}</span>
                <input className={css.input} value={form.name} placeholder={t('fieldNamePlaceholder')} disabled={!writable} onChange={(event) => { setForm({ ...form, name: event.target.value }) }} />
              </label>
              <label className={css.field}>
                <span className={css.label}>{t('fieldUrl')}</span>
                <input className={css.input} value={form.url} placeholder="http://127.0.0.1:8000/v1" inputMode="url" disabled={!writable} onChange={(event) => { setForm({ ...form, url: event.target.value }) }} />
                <span className={css.hint}>{t('fieldUrlHint')}</span>
              </label>
              <label className={css.field}>
                <span className={css.label}>{t('fieldModel')}</span>
                <input className={css.input} value={form.model} disabled={!writable} onChange={(event) => { setForm({ ...form, model: event.target.value }) }} />
                <span className={css.hint}>{t('fieldModelHint')}</span>
              </label>
              <div className={css.row}>
                <label className={css.field}>
                  <span className={css.label}>{t('fieldMode')}</span>
                  <select className={css.input} value={form.mode} disabled={!writable} onChange={(event) => { setForm({ ...form, mode: event.target.value }) }}>
                    <option value="chat">{t('modeChat')}</option>
                    <option value="transcribe">{t('modeTranscribe')}</option>
                  </select>
                </label>
                {form.mode === 'chat'
                  ? (
                    <label className={css.check}>
                      <input type="checkbox" checked={form.speech} disabled={!writable} onChange={(event) => { setForm({ ...form, speech: event.target.checked }) }} />
                      <span>{t('fieldSpeech')}</span>
                    </label>
                  )
                  : null}
              </div>
              <label className={css.field}>
                <span className={css.label}>{t('fieldKeyEnv')}</span>
                <input className={css.input} value={form.keyEnv} placeholder="LAB_AUDIO_API_KEY" disabled={!writable} onChange={(event) => { setForm({ ...form, keyEnv: event.target.value }) }} />
                <span className={css.hint}>{t('fieldKeyEnvHint')}</span>
              </label>
              <div className={css.footer}>
                <span role="status" className={css.muted} data-testid="dsh-audio-servers-status">{status}</span>
                <button type="submit" className={css.primary} disabled={!writable || saving}>{saving ? t('saving') : t('add')}</button>
              </div>
            </form>
          </div>
        )
        : null}
    </li>
  )
}
